const Notifications = () => {
  const notifications = [
    { id: 1, title: 'Order Delivered', desc: 'Order #WW-2024-001 delivered.', time: '17 Jan, 17:15', type: 'order', read: false },
    { id: 2, title: 'Order Shipped', desc: 'Order #WW-2024-002 has been shipped.', time: '16 Jan, 14:45', type: 'order', read: true },
    { id: 3, title: 'Special Offer: 20% Off', desc: 'Use code LUX20 for discount.', time: '15 Jan, 15:30', type: 'promo', read: false },
    { id: 4, title: 'Password Changed', desc: 'Security update successful.', time: '14 Jan, 22:00', type: 'security', read: true },
  ];

  const getIcon = (type) => {
    switch (type) {
      case 'order': return <Truck size={14} className="text-blue-400" />;
      case 'promo': return <TicketIcon />;
      case 'security': return <Lock size={14} className="text-red-400" />;
      default: return <Bell size={14} className="text-[#D4AF37]" />;
    }
  };

  const TicketIcon = () => (
    <svg xmlns="http://www.w3.org/2000/svg" width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="text-emerald-400"><path d="M2 9a3 3 0 0 1 0 6v2a2 2 0 0 0 2 2h16a2 2 0 0 0 2-2v-2a3 3 0 0 1 0-6V7a2 2 0 0 0-2-2H4a2 2 0 0 0-2 2Z" /><path d="M13 5v2" /><path d="M13 17v2" /><path d="M13 11v2" /></svg>
  );

  return (
    <div className="animate-fadeIn">
      <div className="flex justify-between items-center mb-6">
        <SectionHeader title="Notifications" subtitle="3 unread" />
        <button className="text-[#D4AF37] hover:text-white font-outfit text-xs underline transition-colors">Mark all read</button>
      </div>

      {/* Filter Tabs - Scrollable on mobile */}
      <div className="overflow-x-auto pb-2 mb-4">
        <GlassCard className="p-1 inline-flex gap-1 rounded-lg whitespace-nowrap">
          <button className="px-4 py-1.5 bg-[#D4AF37] text-[#0A0604] rounded font-bold font-outfit text-xs shadow-lg">All (4)</button>
          <button className="px-4 py-1.5 hover:bg-white/5 text-white/60 rounded font-bold font-outfit text-xs transition-colors">Orders (2)</button>
          <button className="px-4 py-1.5 hover:bg-white/5 text-white/60 rounded font-bold font-outfit text-xs transition-colors">Promos (1)</button>
        </GlassCard>
      </div>

      <div className="space-y-3">
        {notifications.map((notif) => (
          <GlassCard key={notif.id} className={`p-4 flex gap-3 transition-all ${!notif.read ? 'border-l-2 border-l-[#D4AF37] bg-gradient-to-r from-[#D4AF37]/5 to-transparent' : 'border-l-2 border-l-transparent'}`}>
            <div className={`w-8 h-8 rounded-full flex items-center justify-center shrink-0 ${!notif.read ? 'bg-[#D4AF37]/20' : 'bg-white/5'}`}>
              {getIcon(notif.type)}
            </div>
            <div className="flex-1 min-w-0">
              <div className="flex justify-between items-start mb-0.5">
                <h4 className={`font-outfit text-sm font-bold truncate ${!notif.read ? 'text-white' : 'text-white/70'}`}>
                  {notif.title}
                  {!notif.read && <span className="ml-2 inline-block w-1.5 h-1.5 rounded-full bg-[#D4AF37]"></span>}
                </h4>
                <span className="text-[10px] text-white/30 font-outfit whitespace-nowrap ml-2">{notif.time}</span>
              </div>
              <p className="text-white/50 text-xs font-outfit mb-2 truncate">{notif.desc}</p>
              <div className="flex gap-3">
                <button className="text-[#D4AF37] text-[10px] font-bold uppercase tracking-wider hover:text-white transition-colors">View</button>
                {!notif.read && <button className="text-white/40 text-[10px] font-bold uppercase tracking-wider hover:text-white transition-colors">Read</button>}
              </div>
            </div>
          </GlassCard>
        ))}
      </div>
    </div>
  );
};

