// --- MAIN APP COMPONENT ---

const Account = () => {
  const [activeTab, setActiveTab] = useState('profile'); // Default to profile now
  const [sidebarOpen, setSidebarOpen] = useState(false);

  // --- GOOGLE FONTS INJECTION ---
  useEffect(() => {
    const link = document.createElement('link');
    link.href = 'https://fonts.googleapis.com/css2?family=Outfit:wght@300;400;500;600;700&family=Syncopate:wght@400;700&display=swap';
    link.rel = 'stylesheet';
    document.head.appendChild(link);
    return () => {
      if (document.head.contains(link)) {
        document.head.removeChild(link);
      }
    };
  }, []);

  const handleSignOut = () => {
    localStorage.removeItem('tcr_user');
    localStorage.removeItem('tcr_cart');
    if (window.REACT_APP_NAVIGATE) {
      window.REACT_APP_NAVIGATE('/auth');
    } else {
      console.error("Navigation function not found on window");
      // Fallback if needed, though REACT_APP_NAVIGATE seems to be the standard here
      window.location.href = '/auth';
    }
  };

  const menuItems = [
    // Dashboard removed
    { id: 'profile', label: 'Profile', icon: User },
    { id: 'addresses', label: 'Addresses', icon: MapPin },
    { id: 'orders', label: 'Orders', icon: FileText },
    { id: 'wishlist', label: 'Wishlist', icon: Heart },
    { id: 'payment', label: 'Payments', icon: CreditCard },
    { id: 'notifications', label: 'Alerts', icon: Bell },
    { id: 'support', label: 'Support', icon: Headphones },
    { id: 'logout', label: 'Logout', icon: LogOut, danger: true },
  ];

  const renderContent = () => {
    switch (activeTab) {
      case 'profile': return <ProfileSettings />;
      case 'addresses': return <Addresses />;
      case 'orders': return <Orders />;
      case 'wishlist': return <Wishlist />;
      case 'payment': return <PaymentMethods />;
      case 'notifications': return <Notifications />;
      case 'support': return <SupportTickets />;
      default: return <ProfileSettings />;
    }
  };

  return (
    <div className="min-h-screen bg-[#0A0604] text-gray-200 font-outfit selection:bg-[#D4AF37] selection:text-[#0A0604] overflow-x-hidden pt-20 lg:pt-0">
      {/* Background Ambient Effects */}
      <div className="fixed inset-0 pointer-events-none z-0">
        <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-gradient-to-b from-[#3E2723]/20 to-transparent rounded-full blur-[80px] -translate-y-1/2 translate-x-1/2" />
        <div className="absolute bottom-0 left-0 w-[400px] h-[400px] bg-gradient-to-t from-[#D4AF37]/5 to-transparent rounded-full blur-[100px] translate-y-1/2 -translate-x-1/3" />
      </div>

      {/* Profile Sidebar Toggle - Fixed for mobile */}
      <button
        onClick={() => setSidebarOpen(true)}
        className="lg:hidden fixed bottom-8 left-8 z-[60] w-12 h-12 rounded-full bg-[#D4AF37] text-[#0A0604] shadow-2xl flex items-center justify-center border-2 border-white/20"
      >
        <Menu size={24} />
      </button>

      <div className="relative z-10 flex min-h-screen max-w-[1400px] mx-auto lg:p-6 lg:pt-28 gap-6">

        {/* --- SIDEBAR (Desktop & Mobile Drawer) --- */}
        <aside className={`
                    fixed inset-y-0 left-0 z-[100] w-64 bg-[#0A0604] lg:bg-transparent border-r border-[#D4AF37]/10 lg:border-0 p-5 transform transition-transform duration-300 lg:translate-x-0 lg:static lg:block
                    ${sidebarOpen ? 'translate-x-0 shadow-2xl' : '-translate-x-full'}
                `}>
          <div className="flex items-center justify-between lg:justify-start gap-3 mb-8 px-2">
            <div className="flex items-center gap-3">
              <div className="w-8 h-8 bg-gradient-to-br from-[#D4AF37] to-[#8C7321] rounded rotate-3 shadow-[0_0_10px_rgba(212,175,55,0.3)]"></div>
              <div>
                <h1 className="text-lg font-syncopate font-bold text-white leading-none">THE CHOCOLATE</h1>
                <span className="text-[10px] text-[#D4AF37] font-bold tracking-[0.3em] uppercase block mt-1">ROOM</span>
              </div>
            </div>
            <button onClick={() => setSidebarOpen(false)} className="lg:hidden text-white/50 hover:text-white">
              <X size={20} />
            </button>
          </div>

          <nav className="space-y-1">
            {menuItems.map((item) => {
              const Icon = item.icon;
              return (
                <button
                  key={item.id}
                  onClick={() => {
                    if (item.id === 'logout') {
                      handleSignOut();
                    } else {
                      setActiveTab(item.id);
                      setSidebarOpen(false);
                    }
                  }}
                  className={`
                                        w-full flex items-center gap-3 px-3 py-2.5 rounded-md text-xs font-medium transition-all duration-200 group relative overflow-hidden
                                        ${activeTab === item.id
                      ? 'bg-gradient-to-r from-[#D4AF37] to-[#B4941F] text-[#0A0604] shadow-lg font-bold'
                      : item.danger ? 'text-red-400 hover:bg-red-500/10' : 'text-gray-400 hover:text-white hover:bg-white/5'
                    }
                                    `}
                >
                  {Icon && <Icon size={16} className={activeTab === item.id ? 'animate-pulse' : ''} />}
                  <span className="uppercase tracking-wide">{item.label}</span>
                </button>
              );
            })}
          </nav>

          {/* Member Card */}
          <div className="mt-8 p-4 rounded-xl bg-gradient-to-br from-[#1A110D] to-black border border-[#D4AF37]/20 relative overflow-hidden">
            <div className="absolute top-0 right-0 w-16 h-16 bg-[#D4AF37]/10 rounded-full blur-xl"></div>
            <h4 className="font-syncopate text-[#D4AF37] text-xs font-bold mb-1">Gold Status</h4>
            <p className="text-[10px] text-white/50 mb-3 font-outfit">1,240 Points</p>
            <div className="w-full h-1 bg-white/10 rounded-full overflow-hidden mb-1">
              <div className="h-full bg-[#D4AF37] w-[70%]"></div>
            </div>
          </div>
        </aside>

        {/* Mobile Overlay */}
        {sidebarOpen && (
          <div className="fixed inset-0 bg-black/80 z-40 lg:hidden backdrop-blur-sm" onClick={() => setSidebarOpen(false)}></div>
        )}

        {/* --- MAIN CONTENT --- */}
        <main className="flex-1 w-full min-w-0 p-4 lg:p-0 pt-6 lg:pt-0">
          {renderContent()}
        </main>
      </div>

      <style>{`
                @keyframes fadeIn {
                    from { opacity: 0; transform: translateY(5px); }
                    to { opacity: 1; transform: translateY(0); }
                }
                .animate-fadeIn {
                    animation: fadeIn 0.4s ease-out forwards;
                }
                .font-syncopate {
                    font-family: 'Syncopate', sans-serif;
                }
                .font-outfit {
                    font-family: 'Outfit', sans-serif;
                }
                /* Custom Scrollbar */
                ::-webkit-scrollbar {
                    width: 6px;
                    height: 6px;
                }
                ::-webkit-scrollbar-track {
                    background: #0A0604; 
                }
                ::-webkit-scrollbar-thumb {
                    background: #333; 
                    border-radius: 3px;
                }
                ::-webkit-scrollbar-thumb:hover {
                    background: #D4AF37; 
                }
            `}</style>
    </div>
  );
};

export default Account;
